// ltBudgetBounded names the cells whose SPILLED arm may refuse with a memory
// budget refusal instead of answering: a hash aggregate (DISTINCT, GROUP BY,
// an ungrouped aggregate) or a window over one on a hash join's build side
// at 512 KiB may refuse with `hash join build: memory budget exceeded …
// forced by "spill tracking"` — the upstream breaker's forced spill-tracking
// bytes fill the budget before the build's first reserve. It is
// nondeterministic for the lateral spellings and deterministic for the
// user-written `GROUP BY … QUALIFY` block under a LEFT join, identically at
// 51addfb6: a pre-existing exec/memory defect recorded in arc LT's notes as a
// filing candidate, not a wrong VALUE. The arm either answers PostgreSQL's
// rows or refuses loudly, and this map allows exactly that pair and nothing
// else; the single arm and the three DAG arms assert the rows unconditionally.
var ltBudgetBounded = map[string]bool{

	"LATERAL/distinct/eq":             true,
	"LEFTLATERAL/distinct/eq":         true,
	"COMMALATERAL/distinct/eq":        true,
	"LATERAL/distinct/ineq":           true,
	"LEFTLATERAL/distinct/ineq":       true,
	"COMMALATERAL/distinct/ineq":      true,
	"LATERAL/distinct/mixed":          true,
	"LEFTLATERAL/distinct/mixed":      true,
	"COMMALATERAL/distinct/mixed":     true,
	"LATERAL/distinct/none":           true,
	"COMMALATERAL/distinct/none":      true,
	"LATERAL/distinctOther/eq":        true,
	"LEFTLATERAL/distinctOther/eq":    true,
	"COMMALATERAL/distinctOther/eq":   true,
	"LATERAL/distinctOther/none":      true,
	"COMMALATERAL/distinctOther/none": true,
	"LATERAL/groupHaving/eq":          true,
	"LEFTLATERAL/groupHaving/eq":      true,
	"COMMALATERAL/groupHaving/eq":     true,
	"LATERAL/groupHaving/none":        true,
	"COMMALATERAL/groupHaving/none":   true,
	"LATERAL/groupLimit/eq":           true,
	"LEFTLATERAL/groupLimit/eq":       true,
	"COMMALATERAL/groupLimit/eq":      true,
	"LATERAL/groupLimit/none":         true,
	"COMMALATERAL/groupLimit/none":    true,
	"LATERAL/ungroupedAgg/eq":         true,
	"LEFTLATERAL/ungroupedAgg/eq":     true,
	"COMMALATERAL/ungroupedAgg/eq":    true,
	"LATERAL/ungroupedAgg/none":       true,
	"COMMALATERAL/ungroupedAgg/none":  true,
	"LATERAL/aggHaving/eq":            true,
	"LEFTLATERAL/aggHaving/eq":        true,
	"COMMALATERAL/aggHaving/eq":       true,
	"LATERAL/aggHaving/none":          true,
	"COMMALATERAL/aggHaving/none":     true,
}

// ltArmPins records a disposition that is NOT the same on every arm, per
// arm, with the mechanism. The INNER and comma spellings of a lifted
// predicate over a column the enclosing relation also publishes (#1130) are
// REFUSED on the two single-process arms — which bound the outer column and
// answered no rows — and answer PostgreSQL's rows on the three DAG arms,
// which evaluate the predicate at the join off the scan's own stream (as at
// 51addfb6, on two fixtures; round-2 review B5). The LEFT spellings are
// refused on every arm (ltRefuses): the DAG padded every row NULL on one
// stage shape and routed to the refusal on another for the same statement
// (r2_gates3/4.log). `aliasCollides/shared`'s broadcast and morsel shapes
// refuse with the stage's own `key column "v" does not exist` (L1's LIFTED/*
// class) while the shuffled shape answers.
var ltArmPins = map[string]map[string]string{

	"LATERAL/plain/shared":              {"single": "ERR ~" + ltLiftedRefContested, "spilled512k": "ERR ~" + ltLiftedRefContested},
	"COMMALATERAL/plain/shared":         {"single": "ERR ~" + ltLiftedRefContested, "spilled512k": "ERR ~" + ltLiftedRefContested},
	"LATERAL/limit0/shared":             {"single": "ERR ~" + ltLiftedRefContested, "spilled512k": "ERR ~" + ltLiftedRefContested},
	"COMMALATERAL/limit0/shared":        {"single": "ERR ~" + ltLiftedRefContested, "spilled512k": "ERR ~" + ltLiftedRefContested},
	"LATERAL/aliasCollides/shared":      {"single": "ERR ~" + ltLiftedRefContested, "spilled512k": "ERR ~" + ltLiftedRefContested, "dag": "ERR ~key column \"v\" does not exist in the input schema", "dag-morsel4": "ERR ~key column \"v\" does not exist in the input schema"},
	"COMMALATERAL/aliasCollides/shared": {"single": "ERR ~" + ltLiftedRefContested, "spilled512k": "ERR ~" + ltLiftedRefContested, "dag": "ERR ~key column \"v\" does not exist in the input schema", "dag-morsel4": "ERR ~key column \"v\" does not exist in the input schema"},
}

func TestArcLTACorrelatedBodyIsEvaluatedPerOuterRowOnEveryArm(t *testing.T) {
	if testing.Short() {
		t.Skip("-short: five arms over the 680-cell seam table")
	}
	ctx, cancel := context.WithTimeout(context.Background(), 40*time.Minute)
	t.Cleanup(cancel)
	arms := r1Arms(t, ctx)
	seen := map[string]bool{}
	for _, tc := range ltSeamCells() {
		want, ok := ltPostgres[tc.name]
		if !ok {
			t.Fatalf("%s: no PostgreSQL row set recorded", tc.name)
		}
		seen[tc.name] = true
		t.Run(tc.name, func(t *testing.T) {
			for _, arm := range arms {
				got := arm.run(tc.sql)
				if pins, pinned := ltArmPins[tc.name]; pinned {
					if pin, has := pins[arm.name]; has {
						if strings.HasPrefix(pin, "ERR ~") {
							if !strings.Contains(got, strings.TrimPrefix(pin, "ERR ~")) {
								t.Errorf("%s\n  arm  %s\n  got  %s\n  the pinned refusal (%q) is gone: "+
									"if it answers now, assert PostgreSQL's %s and delete this arm's pin",
									tc.sql, arm.name, got, pin, want)
							}
							continue
						}
						if got == want {
							t.Errorf("%s\n  arm  %s\n  the pinned divergence is GONE and the arm "+
								"answers PostgreSQL's %s: delete this arm's pin", tc.sql, arm.name, want)
							continue
						}
						if got != pin {
							t.Errorf("%s\n  arm  %s\n  got  %s\n  pinned %s (PostgreSQL answers %s)",
								tc.sql, arm.name, got, pin, want)
						}
						continue
					}
				}
				if class, refuses := ltRefuses[tc.name]; refuses {
					if !strings.HasPrefix(got, "ERR ") || !strings.Contains(got, class) {
						t.Errorf("%s\n  arm  %s\n  got  %s\n  every arm must refuse with %q: "+
							"if it answers now, assert PostgreSQL's row set %s and delete this cell's refusal",
							tc.sql, arm.name, got, class, want)
					}
					continue
				}
				if ltBudgetBounded[tc.name] && arm.name == "spilled512k" &&
					strings.HasPrefix(got, "ERR ") && strings.Contains(got, "memory budget exceeded") {
					continue
				}
				if got != want {
					t.Errorf("%s\n  arm  %s\n  got  %s\n  want %s (PostgreSQL 17.11)",
						tc.sql, arm.name, got, want)
				}
			}
		})
	}
	for name := range ltPostgres {
		if !seen[name] {
			t.Errorf("%s: a PostgreSQL row set is recorded for a cell the table no longer writes", name)
		}
	}
}
